export const defaultPrivacy=()=>({realName:false,age:false,location:false,photo:false,publicStory:false});
export function validateDetails(debts){if(!Array.isArray(debts)||!debts.length||debts.length>20)throw Error('Vui lòng thêm từ 1 đến 20 khoản nợ.');for(let i=0;i<debts.length;i++){const d=debts[i];if(!d||typeof d.title!=='string'||!d.title.trim()||d.title.trim().length>100)throw Error(`Khoản nợ ${i+1}: nhập tiêu đề từ 1–100 ký tự.`);if(typeof d.story!=='string'||!d.story.trim()||d.story.trim().length>3000)throw Error(`Khoản nợ ${i+1}: nhập câu chuyện từ 1–3.000 ký tự.`);if(!Number.isSafeInteger(d.amount)||d.amount<=0||d.amount>1e12)throw Error(`Khoản nợ ${i+1}: nhập số tiền nợ nguyên dương, tối đa 1.000 tỷ VNĐ.`);}return debts.map(d=>({title:d.title.trim(),story:d.story.trim(),amount:d.amount}));}
export function publicCard(debts,privacy,identity={}){return {name:privacy.realName&&identity.name?identity.name:identity.nickname||'Broke ẩn danh',...(privacy.age&&identity.age?{age:identity.age}:{}),...(privacy.location&&identity.location?{location:identity.location}:{}),...(privacy.photo&&identity.photo?{photo:identity.photo}:{}),debts:debts.map(d=>({title:d.title,...(Number.isSafeInteger(d.amount)?{amount:d.amount}:{}),...(privacy.publicStory?{story:d.story}:{})}))};}

